import{_ as i,o as a,c as t,ag as l}from"./chunks/framework.D9ghT4bC.js";const c=JSON.parse('{"title":"指导原则","description":"","frontmatter":{},"headers":[],"relativePath":"zh/Guiding-Principles.md","filePath":"zh/Guiding-Principles.md"}'),o={name:"zh/Guiding-Principles.md"};function n(u,e,r,p,s,d){return a(),t("div",null,[...e[0]||(e[0]=[l('<h1 id="指导原则" tabindex="-1">指导原则 <a class="header-anchor" href="#指导原则" aria-label="Permalink to &quot;指导原则&quot;">​</a></h1><h2 id="ai-的目标是求胜" tabindex="-1">AI 的目标是求胜 <a class="header-anchor" href="#ai-的目标是求胜" aria-label="Permalink to &quot;AI 的目标是求胜&quot;">​</a></h2><p>在一个理想的世界里，AI 能通过游戏性的&quot;图灵测试&quot;——你分辨不出自己是在和人类还是 AI 对战。</p><p>例如：</p><ul><li>不会问&quot;你要拿什么换这个&quot;</li><li>如果你的军事力量薄弱，AI 会主动进攻你（你落难时它真的会踩你一脚）</li></ul><p>在交易方面，&quot;可被利用&quot;与&quot;没意思&quot;之间有一条微妙的线——普通玩家可能出于原则拒绝你的任何交易。 我们不希望 AI 也这样，这让我们稍微容易被利用，但这是我们清醒认识到的权衡。</p><h2 id="模组哲学——最少对象-最大交互" tabindex="-1">模组哲学——最少对象，最大交互 <a class="header-anchor" href="#模组哲学——最少对象-最大交互" aria-label="Permalink to &quot;模组哲学——最少对象，最大交互&quot;">​</a></h2><p>作为新模组制作者，很容易迷失在数量庞大的 unique 中。</p><p>我们的目标是把 unique 的<em>数量</em>降到最低，但通过允许组合来促成&quot;涌现式模组&quot;。</p><p>例如：</p><ul><li>unique 中的参数 &gt; 多个 unique</li><li>条件应该是 Conditionals（条件修饰符），这样它们可以应用到所有 unique 上</li><li>触发型 unique 与 unique 触发器——所有组合</li><li>单位行动修饰符，而不是为特定单位行动设置特殊属性</li></ul><h2 id="尽早崩溃-经常崩溃" tabindex="-1">尽早崩溃，经常崩溃 <a class="header-anchor" href="#尽早崩溃-经常崩溃" aria-label="Permalink to &quot;尽早崩溃，经常崩溃&quot;">​</a></h2><p>崩溃堆栈离解决方案已经走了一半——一个能稳定复现它的存档则完成了 90%。</p><p>每当意外情况发生——游戏到达了非法状态——我们就应该崩溃，让问题尽早被修复。坚持错误的运行状态会让最终的问题离根因更远，并使调试复杂化。</p><p>然而，我们绝不应因为糟糕的<em>用户输入</em>而崩溃。糟糕的输入——例如定义不当的模组——<em>是</em>预期内的，应该妥善处理。</p><p>这类似于 http 4XX 和 5XX 的区别——坏输入在与外部世界的接口处是预期的，坏内部状态则是意外的。</p><p>两种情况的共同目标是<em>尽量减少崩溃</em>，只是方法不同。</p>',17)])])}const q=i(o,[["render",n]]);export{c as __pageData,q as default};
